// Seven-day idea plan. Media starts only when an individual idea is approved.
const action = 'plan_campaign'; // plan_campaign | sync | start_batch | resume_batch | release_batch | status
const timezone = 'America/New_York';
const localNow = $now.setZone(timezone);
const daysUntilMonday = ((8 - localNow.weekday) % 7) || 7;
const startDate = localNow.plus({ days: daysUntilMonday }).toFormat('yyyy-MM-dd');
const name = `GymFeed weekly ideas ${startDate}`;
const days = 7;
const campaignId = ''; // Copy from planning result for sync/recovery/status actions.
const batchId = ''; // Copy from a production result for resume/release.
const batchNumber = 1; // Legacy/manual recovery only; normal approval starts one item directly.
const requestKey = ''; // Keep unchanged when retrying the same operation.

if (action === 'plan_campaign') {
  return [{ json: { action, name, startDate, days, timezone, requestKey: requestKey || `campaign:${name}:${startDate}:${days}:${timezone}` } }];
}
if (!campaignId) throw new Error('Set campaignId from the existing campaign result; do not create a new campaign to resume one.');
if (action === 'start_batch') {
  return [{ json: { action, campaignId, batchNumber, requestKey: requestKey || `campaign:${campaignId}:batch:${batchNumber}` } }];
}
if (action === 'resume_batch' || action === 'release_batch') {
  if (!batchId) throw new Error('Set batchId from the production result.');
  return [{ json: { action, campaignId, batchId } }];
}
if (action === 'status' || action === 'sync') return [{ json: { action, campaignId } }];
throw new Error(`Unsupported manual action: ${action}`);
